INSERT INTO [sync].[BuyKitchenProductProperties] ([id], [model], [name], [property], [value], [sort]) VALUES (N'82322', N'C5102-SV206', N'SAKURA STONE石英石檯面', N'表面處理', N'亮面', N'3')
