INSERT INTO [sync].[BuyKitchenProductProperties] ([id], [model], [name], [property], [value], [sort]) VALUES (N'82322', N'C5102-SV206', N'SAKURA STONE石英石檯面', N'詳細規格', N'《SAKURA stone 櫻花石英石》 以世界領先工藝生產的超硬環保複合石英結晶體為材料，93%的石英主結構，經過32道表面拋光工藝，使外觀近似天然花崗石。 具真空合成、緻密無孔的超強硬度表面，不易刮花、汙染、燃燒，且抗菌、耐久、無毒、無輻射。 在光澤、質感和液體防滲、防汙方面超越天然石或其他人造石，為可直接與食物接觸的安全材質，特別適合台灣廚房環境。', N'4')
GO

INSERT INTO [sync].[BuyKitchenProductProperties] ([id], [model], [name], [property], [value], [sort]) VALUES (N'82322', N'C5102-SV206', N'SAKURA STONE石英石檯面', N'詳細規格', N'【高耐汙 易清潔】 吸水率僅≦0.05%，表面幾乎密封不滲水，不易受咖啡、茶等液體滲透染色。日常清潔只需用清水及中性清潔劑擦拭即可。', N'5')
GO

INSERT INTO [sync].[BuyKitchenProductProperties] ([id], [model], [name], [property], [value], [sort]) VALUES (N'82322', N'C5102-SV206', N'SAKURA STONE石英石檯面', N'詳細規格', N'【耐酸鹼 抗腐蝕】 具有較強抗化學腐蝕性，抗酸耐鹼，長時間使用不會產生變色、褪色等問題，是經久耐用的放心產品。', N'6')
GO

INSERT INTO [sync].[BuyKitchenProductProperties] ([id], [model], [name], [property], [value], [sort]) VALUES (N'82322', N'C5102-SV206', N'SAKURA STONE石英石檯面', N'詳細規格', N'【高硬度 超耐磨】 硬度高達莫氏硬度7.0，極耐刮。可防止刀、鏟等利器意外刮傷檯面。但檯面上切剁食材時，仍需使用砧板，避免不均受力。', N'7')
GO

INSERT INTO [sync].[BuyKitchenProductProperties] ([id], [model], [name], [property], [value], [sort]) VALUES (N'82322', N'C5102-SV206', N'SAKURA STONE石英石檯面', N'詳細規格', N'【高耐熱 不變形】 不會出現因炊具、爐火等高溫加熱而造成的軟化、凹痕、焦斑等現象。其熱脹冷縮性能穩定，長期使用不變形，無拼接處翹起問題。', N'8')
