INSERT INTO [sync].[BuyKitchenProductProperties] ([id], [model], [name], [property], [value], [sort]) VALUES (N'82335', N'C5112-SV9210', N'SAKURA STONE石英石檯面', N'詳細規格', N'《SAKURA stone 櫻花石英石》 以世界領先工藝生產的超硬環保複合石英結晶體為材料，93%的石英主結構，經過32道表面拋光工藝，使外觀近似天然花崗石。 具真空合成、緻密無孔的超強硬度表面，不易刮花、汙染、燃燒，且抗菌、耐久、無毒、無輻射。 在光澤、質感和液體防滲、防汙方面超越天然石或其他人造石，為可直接與食物接觸的安全材質，特別適合台灣廚房環境。', N'4')
GO

