INSERT INTO [sync].[BuyKitchenProductProperties] ([id], [model], [name], [property], [value], [sort]) VALUES (N'82177', N'D1180', N'MFC四邊封門板', N'詳細規格', N'以直向木紋壓紋呈現細緻紋理，灰綠色調沉穩內斂，如森林深處的靜謐光影，為空間帶來平和與深度，營造低調卻耐看的自然氣息。', N'8')
